import type { AppOrElementRef, FieldRef, RecordIdentityRef, TableColumnRef, TableRef } from "../../catalog/index.js";
import type { Filter } from "../shared/filters/types.js";
import type { AppViewFieldRef } from "../app/build.js";
export interface AppRelationshipColumn<Target extends AppOrElementRef | TableRef = AppOrElementRef | TableRef> {
    /** Field on the owning app/element. */
    readonly field: AppViewFieldRef;
    /** Field/column on `target`. */
    readonly relatedField: FieldRef | TableColumnRef | RecordIdentityRef<Target>;
}
/**
 * A parent-owned join (`elementum_relationship`) keyed under this app/element's
 * `relationships` bag. `relatedRecords` widgets on this object list rows
 * through these joins. Columns must join comparable stored values; do not
 * join this object's system `"id"` (HANDLE) to a child `relationField`.
 * A child `relationField` / `autoRelate` is not a substitute for a join
 * owned here.
 */
export interface AppRelationship<Target extends AppOrElementRef | TableRef = AppOrElementRef | TableRef> {
    readonly target: Target;
    readonly columns: readonly AppRelationshipColumn<Target>[];
    /** Uses the same typed filter DSL as access policies. */
    readonly filter?: Filter;
}
